using System.Net.Http.Json;using System.Text.Json;using System.Text.Json.Nodes;using Microsoft.Data.Sqlite;using Microsoft.Extensions.DependencyInjection;namespace DrillingOperations.Tests;
[TestFixture,NonParallelizable]public sealed class LogVersionCompatibilityTests{
[Test]public async Task V1WithoutS6Provenance_FailsExplicitly_WhileV2RestartsAndReachesS6(){await using var factory=new ApiFactory();using var client=factory.CreateInternalClient();using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(TestData.Binding())};bind.Headers.Add("Idempotency-Key","log-version-bind");(await client.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run())};create.Headers.Add("Idempotency-Key","log-version-run");var created=await client.SendAsync(create);RunResponse run=JsonSerializer.Deserialize<RunResponse>(await created.Content.ReadAsStringAsync(),CanonicalJson.SerializerOptions)!;for(int i=0;i<300;i++){var current=(await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{run.RunId}",CanonicalJson.SerializerOptions))!;if(current.Status==RunStatus.AwaitingApproval&&current.CurrentStage==RunStageKind.S6DesignCompletion)break;if(i==299)Assert.Fail("Run did not reach S6 approval.");await Task.Delay(25);}var store=factory.Services.GetRequiredService<DrillingOperationsStore>();LogObservationArtifact v2=(await store.GetLogObservationBatchAsync(run.RunId))!;Assert.That(v2.ObservationModelVersion,Is.EqualTo("synthetic-petrophysics-v2"));var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();Assert.That(CanonicalJson.Serialize(await restarted.GetLogObservationBatchAsync(run.RunId)),Is.EqualTo(CanonicalJson.Serialize(v2)));await using var db=new SqliteConnection($"Data Source={factory.DatabasePath}");await db.OpenAsync();string output;await using(var read=db.CreateCommand()){read.CommandText="SELECT CanonicalOutputJson FROM ObservationBatches WHERE RunId=$run AND Stage=$stage";read.Parameters.AddWithValue("$run",run.RunId);read.Parameters.AddWithValue("$stage",(int)RunStageKind.S5GenerateLogs);output=(string)(await read.ExecuteScalarAsync())!;}JsonObject legacy=JsonNode.Parse(output)!.AsObject();legacy.Remove("sourcePathBindingId");legacy["observationModelVersion"]="synthetic-petrophysics-v1";string legacyJson=CanonicalJson.Canonicalize(JsonSerializer.SerializeToElement(legacy,CanonicalJson.SerializerOptions));await using(var mutate=db.CreateCommand()){mutate.CommandText="DROP TRIGGER TR_ObservationBatches_NoUpdate;UPDATE ObservationBatches SET ObservationModelVersion=$version,CanonicalOutputJson=$output,OutputHash=$hash WHERE RunId=$run AND Stage=$stage";mutate.Parameters.AddWithValue("$version","synthetic-petrophysics-v1");mutate.Parameters.AddWithValue("$output",legacyJson);mutate.Parameters.AddWithValue("$hash",DeterministicIdentity.Sha256(legacyJson));mutate.Parameters.AddWithValue("$run",run.RunId);mutate.Parameters.AddWithValue("$stage",(int)RunStageKind.S5GenerateLogs);await mutate.ExecuteNonQueryAsync();}PersistenceIntegrityException incompatible=Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restarted.GetLogObservationBatchAsync(run.RunId))!;Assert.That(incompatible.Message,Is.EqualTo("synthetic-petrophysics-v1 is incompatible with S6 provenance; a new scenario and run are required."));await using(var future=db.CreateCommand()){future.CommandText="UPDATE ObservationBatches SET ObservationModelVersion=$version WHERE RunId=$run AND Stage=$stage";future.Parameters.AddWithValue("$version","synthetic-petrophysics-v99");future.Parameters.AddWithValue("$run",run.RunId);future.Parameters.AddWithValue("$stage",(int)RunStageKind.S5GenerateLogs);await future.ExecuteNonQueryAsync();}PersistenceIntegrityException unknown=Assert.ThrowsAsync<PersistenceIntegrityException>(async()=>await restarted.GetLogObservationBatchAsync(run.RunId))!;Assert.That(unknown.Message,Does.Contain("Unsupported log observation model version synthetic-petrophysics-v99"));}
}
